'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uuid=()=>globalThis.crypto?.randomUUID?.()||Array.from(globalThis.crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join('');
const money=n=>'රු. '+((n||0)/100).toLocaleString('en-LK',{minimumFractionDigits:2,maximumFractionDigits:2});
const dt=s=>s?new Date(s).toLocaleString('en-GB',{timeZone:'Asia/Colombo'}):'—';
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Colombo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
let D=null,U=null,T='dashboard',DIRTY=false,BUSY=false,FILTER={q:'',project:'',status:'',from:'',to:'',user:''},DRIVE='',driveToken='',driveExpires=0,restoreFile=null;
const A=()=>U?.role==='admin',name=id=>D?.users.find(u=>u.id===id)?.name||'පැරණි භාරකරු',pn=id=>D?.projects.find(p=>p.id===id)?.name||'පැරණි project',item=id=>D?.items.find(i=>i.id===id)?.name||'—';
const statuses={pending:'Pending',approved:'Approved',received:'ලැබුණා',rejected:'Rejected',reversed:'Reversed',cancelled:'Cancelled',complete:'Complete',ongoing:'ක්‍රියාත්මක',hold:'On hold',done:'Completed',archived:'Archived'};
const badge=s=>`<span class="badge ${esc(s)}">${esc(statuses[s]||s)}</span>`;
const btn=(label,action,id='',cls='secondary small',extra='')=>`<button type="button" class="${cls}" data-action="${esc(action)}" data-id="${esc(id)}" ${extra}>${esc(label)}</button>`;
const empty=s=>`<div class="empty">${esc(s||'තවම records නැහැ')}</div>`;
const field=(label,key,type='text',value='',required=false,attrs='')=>`<label class="field"><span>${esc(label)}</span><input name="${key}" type="${type}" value="${esc(value)}" ${required?'required':''} ${attrs}></label>`;
const select=(label,key,options,selected='',required=false)=>`<label class="field"><span>${esc(label)}</span><select name="${key}" ${required?'required':''}>${options.map(o=>`<option value="${esc(o[0])}" ${String(o[0])===String(selected)?'selected':''}>${esc(o[1])}</option>`).join('')}</select></label>`;
const noteField=(label='විස්තරය',key='note',required=false)=>`<label class="field"><span>${esc(label)}</span><textarea name="${key}" ${required?'required':''} maxlength="300"></textarea></label>`;
const check=(label,key)=>`<label class="field check"><input type="checkbox" name="${key}">${esc(label)}</label>`;
const photoField=()=>field('Receipt / Site photo (JPG / PNG, ≤ 3 MB)','photo','file','','', 'accept="image/jpeg,image/png"')+'<p class="photo-note">පැහැදිලි photo එකක් තෝරන්න. Original file එක 3 MB ඉක්මවුවොත් upload කිරීමට පෙර කුඩා කරන්න.</p>';
const projects=()=>D.projects.filter(p=>p.status==='ongoing');
const pselect=(optional=false,list=projects(),selected='')=>select('Project','project',[["",optional?'සියල්ල / අදාළ නැත':'තෝරන්න'],...list.map(p=>[p.id,p.name])],selected,!optional);
const supervisors=()=>D.users.filter(u=>u.role==='supervisor'&&u.active);
const suselect=(key='to',selected='')=>select('Supervisor',key,[['','තෝරන්න'],...supervisors().map(u=>[u.id,u.name])],selected,true);
const form=(op,content,label='Save',hidden={})=>`<form data-op="${op}">${Object.entries(hidden).map(([k,v])=>`<input type="hidden" name="${k}" value="${esc(v)}">`).join('')}${content}<div class="form-error" role="alert"></div><button type="submit">${esc(label)}</button></form>`;
const card=(title,html)=>`<section class="card"><h2>${esc(title)}</h2>${html}</section>`;
const amount=()=>field('මුදල (රු.)','amount','number','',true,'min="0.01" max="1000000000" step="0.01"');
const quantity=(value=1)=>field('ගණන','quantity','number',value,true,'min="1" max="1000000" step="1"');
const receipt=url=>{try{const u=new URL(url);if(u.protocol!=='https:'||u.origin!==new URL(EB_CONFIG.supabaseUrl).origin)return '';return `<a class="receipt-link" href="${esc(url)}" target="_blank" rel="noopener"><img class="photo" loading="lazy" src="${esc(url)}" alt="Receipt / Site photo"></a>`;}catch{return '';}};
const total=(list,key='amount')=>list.reduce((s,r)=>s+(r[key]||0),0);
const activeSup=p=>{const at=new Date().toISOString(),h=D.handovers.slice().reverse().find(h=>h.project===p.id&&h.temporary&&h.status==='complete'&&h.start<=at&&at<h.end);return h?h.to:p.supervisor;};
let STATE_REQUEST=0,CONNECTED=false,INSTALL_PROMPT=null;
function connection(ok){CONNECTED=ok;const el=$('.connection');if(el){el.className='connection '+(ok?'':'offline');el.textContent=(ok?'● Server connected':'● Server disconnected')+' · '+queue().length+' queued';}}
const canWrite=()=>!U?.mustChange;
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function modal(title,html){$('#modalBody').innerHTML=`<h2>${esc(title)}</h2>${html}`;$('#modal').showModal();}
function closeModal(){const m=$('#modal');if(m.open)m.close();$('#modalBody').innerHTML='';DIRTY=false;}
async function api(path='/api/state',data=null){try{const result=await EBCloud.request(path,data);connection(true);return result;}catch(e){connection(!!e.status);if(!e.status)e.network=true;throw e;}}
async function refresh(renderNow=true){const ticket=++STATE_REQUEST;try{const r=await api();if(ticket!==STATE_REQUEST)return;if(r.setup){D=null;U=null;renderAuth(true);return;}D=r.data;U=r.user;DRIVE=r.driveClientId||'';if(DRIVE)loadGoogle().catch(()=>{});if(U.mustChange)T='settings';if(renderNow&&(!DIRTY||U.mustChange)&&!$('#modal').open)render();}catch(e){if(ticket!==STATE_REQUEST)return;if(e.status===401){U=null;D=null;renderAuth(false);}else if(!U){$('#app').innerHTML=card('Server සම්බන්ධ නැහැ','<p>Internet connection සහ cloud configuration පරීක්ෂා කර නැවත උත්සාහ කරන්න.</p>'+btn('නැවත උත්සාහ කරන්න','refresh'));}else toast(e.message);}}
function legacyNotice(){try{const old=JSON.parse(localStorage.getItem('eb2')||'{}'),queue=JSON.parse(localStorage.getItem('ebq')||'[]');if(!['p','tx','bl','d','c'].some(k=>Array.isArray(old[k])&&old[k].length)&&!(Array.isArray(queue)&&queue.length))return '';return `<div class="note">මේ browser එකේ පැරණි app data තිබෙනවා. ඒවා මකා නැහැ; cloud එකට ස්වයංක්‍රීයව import කර නැහැ. මුලින් export copy එකක් ගන්න.<br>${btn('පැරණි data export','legacy-export')}</div>`;}catch{return '';}}
function renderAuth(setup){$('#app').innerHTML=`<div class="auth card"><img class="logo" src="./logo.png" alt="Early Birds"><h1>${setup?'ඔබේ workspace එක':'නැවත සාදරයෙන්'}</h1><p class="subtitle">EARLY BIRDS · PROJECT MANAGER</p>${form(setup?'setup':'login',(setup?field('Admin නම','name','text','',true):'')+field('Email','username','email','',true,'autocomplete="username" minlength="3"')+field(setup?'Password (අකුරු 10+)':'Password','password','password','',true,`autocomplete="${setup?'new-password':'current-password'}" minlength="${setup?10:1}" maxlength="256"`)+(setup?field('Password නැවත','password2','password','',true,'minlength="10"')+field('Remote setup token (localhost නම් හිස්ව තබන්න)','setupToken'):' '),setup?'Admin account හදන්න':'Login')}${legacyNotice()}<p class="footer">${setup?'මුල් setup එක server computer එකේ localhost එකෙන් කරන්න.':'ඔබේ cloud account email සහ password භාවිතා කරන්න. Public signup නැහැ.'}</p></div>`;}
const tabs=()=>A()?[['dashboard','◈','Dashboard'],['projects','▦','Projects'],['money','↗','මුදල්'],['bills','▤','Bills'],['stores','▣','Stores'],['handover','⇄','Handover'],['reports','▥','Reports'],['users','♙','Users'],['settings','⚙','Settings']]:[['dashboard','◈','Home'],['projects','▦','Projects'],['money','↗','මුදල්'],['attendance','◎','Check-in'],['daily','▤','දෛනික'],['bills','▧','Bills'],['stores','▣','Stores'],['handover','⇄','භාරගැනීම්'],['settings','⚙','මම']];
function render(){if(!U)return;const list=tabs();if(!list.some(t=>t[0]===T))T='dashboard';const title=list.find(t=>t[0]===T)[2];$('#app').innerHTML=`<header><div class="brand"><img src="./logo.png" alt="Early Birds"><div><strong>EARLY BIRDS</strong><small>BUILD WITH CONFIDENCE</small></div></div><div class="account"><div>${esc(U.name)}<small>${A()?'ADMIN':'SUPERVISOR'}</small></div>${btn('Install','install')}${btn('Logout','logout')}</div></header><main><div class="layout"><nav class="sidebar" aria-label="Main navigation"><span class="section-label">WORKSPACE</span>${list.map(([id,icon,n])=>`<button data-tab="${id}" class="${id===T?'active':''}" ${U.mustChange&&id!=='settings'?'disabled':''}><b>${icon}</b>${esc(n)}</button>`).join('')}</nav><div><div class="topline"><h1>${esc(title)}</h1><div class="actions"><span class="connection ${CONNECTED?'':'offline'}">${CONNECTED?'● Server connected':'● Server disconnected'} · ${queue().length} queued</span>${btn('Refresh','refresh')}</div></div><p class="subtitle">${today()} · ශ්‍රී ලංකා වේලාව · ${A()?'ඔබේ සියලු projects එකම තැනක':'ඔබට ලබාදී ඇති වැඩ සහ ගනුදෙනු'}</p>${legacyNotice()}${EBCloud.mode==='existing'?'<div class="note">Phone preview: existing cloud data සම්බන්ධයි. සම්පූර්ණ fixes සහ handover සඳහා reviewed backend update එක activate කළ යුතුයි. මුදල් අලුතින් යැවීම දැනට block කර ඇත.</div>':''}${U.mustChange?'<div class="note">මුලින් Admin ලබාදුන් temporary password වෙනස් කරන්න.</div>':views[T]()}${U.mustChange?settings():''}<p class="footer">Early Birds Phone · Secure cloud workspace</p></div></div></main>`;}
const stat=(label,value,sub='')=>`<div class="card stat"><small>${esc(label)}</small><strong>${esc(value)}</strong><span>${esc(sub)}</span></div>`;
function dashboard(){const pendingBills=D.bills.filter(x=>x.status==='pending'),pendingR=D.requests.filter(x=>x.status==='pending'),active=projects();const b=A()?total(Object.values(D.balances).map(amount=>({amount}))):D.balances[U.id]||0;return `<div class="stats">${stat('ACTIVE PROJECTS',active.length,'ක්‍රියාත්මක ව්‍යාපෘති')}${stat(A()?'SUPERVISOR BALANCES':'CONFIRMED BALANCE',money(b),'Approved expenses පමණක් අඩු වේ')}${stat('PENDING BILLS',pendingBills.length,money(total(pendingBills)))}${stat('REQUESTS',pendingR.length,'මුදල් ඉල්ලීම්')}</div><div class="grid">${card('Project overview',D.projects.slice(0,6).map(p=>`<div class="row"><div><strong>${esc(p.name)}</strong><small> · ${esc(name(activeSup(p)))}</small><div class="progress"><i style="width:${Number(p.progress)}%"></i></div><small>${p.progress}% · ${esc(p.location)}</small></div>${badge(p.status)}</div>`).join('')||empty())}${card('අවධානය අවශ්‍යයි',`<div class="row"><span>ලැබීම තහවුරු නොකළ මුදල්</span><strong>${D.transfers.filter(t=>t.status==='pending').length}</strong></div><div class="row"><span>Stock requests / returns</span><strong>${D.stockRequests.filter(r=>r.status==='pending').length}</strong></div><div class="row"><span>Pending handovers</span><strong>${D.handovers.filter(h=>h.status==='pending').length}</strong></div><div class="row"><span>Offline queue</span><strong>${queue().length}</strong>${btn('Sync queue','sync')}</div>`)} </div>${A()?card('නවතම ක්‍රියාකාරකම්',D.audit.slice(-8).reverse().map(r=>`<div class="row"><span>${esc(name(r.user))} · ${esc(r.action)}</span><small>${dt(r.time)}</small></div>`).join('')||empty()):card('Pending receipts',D.transfers.filter(t=>t.to===U.id&&t.status==='pending').map(t=>`<div class="row"><span>${money(t.amount)} · ${esc(pn(t.project))}</span>${btn('ලැබුණා','receive',t.id)}</div>`).join('')||empty('ලැබීම තහවුරු කළ යුතු මුදල් නැහැ'))}`;}
function projectForm(p={}){return form('project.save',field('Project නම','name','text',p.name||'',true)+field('ස්ථානය','location','text',p.location||'')+suselect('supervisor',p.supervisor||'')+`<div class="form-grid">${field('ආරම්භ දිනය','start','date',p.start||today(),true)}${field('අවසන් දිනය','end','date',p.end||today(),true)}${field('Budget (රු.)','budget','number',(p.budget||0)/100,true,'min="0" max="1000000000" step="0.01"')}${field('Progress %','progress','number',p.progress||0,true,'min="0" max="100" step="1"')}${field('Latitude','lat','number',p.lat??'',false,'min="-90" max="90" step="any"')}${field('Longitude','lng','number',p.lng??'',false,'min="-180" max="180" step="any"')}</div>`+btn('දැන් ඉන්න තැන ගන්න','gps-project')+field('Check-in radius (m)','radius','number',p.radius||1000,true,'min="50" max="5000"')+select('තත්ත්වය','status',['ongoing','hold','done','archived'].map(v=>[v,statuses[v]]),p.status||'ongoing',true)+(p.id?'<p class="note">Supervisor මාරු කිරීමට Handover tab භාවිතා කරන්න.</p>':''),'Save',{id:p.id||'',revision:D.revision});}
function projectsView(){return `${A()?`<div class="actions no-print">${btn('＋ Project එකතු කරන්න','project-new','','','')}</div>`:''}${filterBar(false)}<div class="grid">${filtered(D.projects).map(p=>{const approved=total(D.bills.filter(b=>b.project===p.id&&b.status==='approved')),pending=total(D.bills.filter(b=>b.project===p.id&&b.status==='pending'));const eq=D.equipment.filter(e=>e.project===p.id&&e.quantity>0);return card(p.name,`<div class="row"><span>${esc(p.location)}</span>${badge(p.status)}</div><p><small>Supervisor</small><br><strong>${esc(name(activeSup(p)))}</strong></p><div class="progress"><i style="width:${p.progress}%"></i></div><div class="row"><small>${p.progress}% complete</small><small>${esc(p.start)} → ${esc(p.end)}</small></div><div class="split-total">Budget: ${money(p.budget)}<br>Approved: <span class="${approved>p.budget?'negative':''}">${money(approved)}</span><br>Pending: ${money(pending)}</div><p><small>GPS: ${p.lat===null?'සකස් කර නැහැ':`${p.lat}, ${p.lng} · ${p.radius}m`}</small></p><h3>Equipment</h3>${eq.map(e=>`<div class="row"><span>${esc(item(e.item))} × ${e.quantity}</span></div>`).join('')||empty('Equipment නැහැ')}${A()?btn('Edit','project-edit',p.id):''}`);}).join('')||empty()}</div>`;}
function filterBar(project=true){return `<div class="toolbar no-print"><input data-filter="q" placeholder="Search…" aria-label="Search" value="${esc(FILTER.q)}">${project?`<select data-filter="project" aria-label="Filter project"><option value="">සියලු projects</option>${D.projects.map(p=>`<option value="${p.id}" ${p.id===FILTER.project?'selected':''}>${esc(p.name)}</option>`).join('')}</select>`:''}<select data-filter="status" aria-label="Filter status"><option value="">සියලු status</option>${['pending','approved','rejected','received','ongoing','hold','done','archived'].map(s=>`<option value="${s}" ${s===FILTER.status?'selected':''}>${statuses[s]}</option>`).join('')}</select>${A()?`<select data-filter="user" aria-label="Filter Supervisor"><option value="">සියලු Supervisors</option>${D.users.filter(u=>u.role==='supervisor').map(u=>`<option value="${u.id}" ${u.id===FILTER.user?'selected':''}>${esc(u.name)}</option>`).join('')}</select>`:''}<input type="date" data-filter="from" aria-label="From date" value="${esc(FILTER.from)}"><input type="date" data-filter="to" aria-label="To date" value="${esc(FILTER.to)}"></div>`;}
function filtered(rows){return rows.filter(r=>(!FILTER.project||r.project===FILTER.project||r.id===FILTER.project)&&(!FILTER.status||r.status===FILTER.status)&&(!FILTER.user||(r.user||r.supervisor||r.holder)===FILTER.user)&&(!FILTER.q||[r.name,r.note,r.code,r.location,r.stage,pn(r.project),name(r.user)].join(' ').toLowerCase().includes(FILTER.q.toLowerCase()))&&(!FILTER.from||(r.date||r.time||r.start||'').slice(0,10)>=FILTER.from)&&(!FILTER.to||(r.date||r.time||r.start||'').slice(0,10)<=FILTER.to));}
let LIMIT=40;
function table(headers,rows){const shown=rows.slice(0,LIMIT);return rows.length?`<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${shown.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${rows.length>LIMIT?btn(`තවත් පෙන්වන්න (${rows.length-LIMIT})`,'more'):''}`:empty();}
function moneyView(){const mybal=D.balances[U.id]||0;const requestRows=filtered(D.requests).slice().reverse();return `${A()?card('මුදල් යවන්න',form('money.send',suselect()+pselect(true)+amount()+select('Approved requests දැනටමත් pending transfer සාදයි','request',[['','වෙනම මුදල් යැවීම'],...D.requests.filter(r=>r.status==='approved').map(r=>[r.id,`${name(r.user)} · ${pn(r.project)} · ${money(r.amount)}`])])+noteField(),'Send — ලැබීම තහවුරු කළ යුතුයි')):card('මගේ confirmed balance',`<strong class="${mybal<0?'negative':'positive'}" style="font-size:28px">${money(mybal)}</strong><p class="muted">${mybal<0?'ඔබට ආපසු ගෙවිය යුතු මුදල':'ඔබ භාරයේ ඇති මුදල'} · Pending bills වෙනම පෙන්වයි.</p>`)+`<div class="grid">${card('මුදල් ඉල්ලන්න',form('money.request',pselect()+amount()+noteField(),'Request'))}${card('මුදල් Adminට ආපසු දෙන්න',form('money.return',pselect(true,D.projects)+amount()+noteField(),'Return — Admin තහවුරු කළ යුතුයි'))}</div>`}${A()?card('Supervisor balances',table(['Supervisor','Confirmed balance','Pending bills'],D.users.filter(u=>u.role==='supervisor').map(u=>[esc(u.name),`<strong class="${D.balances[u.id]<0?'negative':''}">${money(D.balances[u.id])}</strong>`,money(total(D.bills.filter(b=>b.user===u.id&&b.status==='pending')))]))):''}${filterBar()}${card('මුදල් ඉල්ලීම්',table(['කවුරුන් / Project','මුදල','Status','Actions'],requestRows.map(r=>[`${esc(name(r.user))}<br><small>${esc(pn(r.project))} · ${dt(r.time)}</small><br>${esc(r.note)}`,money(r.amount),badge(r.status)+(r.reason?`<br><small>${esc(r.reason)}</small>`:''),A()&&r.status==='pending'?btn('Approve & queue transfer','request-approve',r.id)+btn('Reject','request-reject',r.id,'danger small'):'—'])))}${card('මුදල් ගනුදෙනු',table(['යැවූ / ලැබෙන කෙනා','මුදල','Status','Actions'],filtered(D.transfers).slice().reverse().map(t=>[`${esc(name(t.from))} → ${esc(name(t.to))}<br><small>${esc(pn(t.project))} · ${dt(t.time)}</small><br>${esc(t.note)}`,money(t.amount),badge(t.status),t.status==='pending'?`${t.to===U.id?btn('ලැබුණා','receive',t.id):''}${t.from===U.id?btn('Cancel','money-cancel',t.id,'danger small'):''}`:A()&&t.status==='received'?btn('Reverse','money-reverse',t.id,'danger small'):'—'])))} `;}
function billsView(){return `${!A()?card('Expense submit කරන්න',form('bill.add',pselect()+select('වර්ගය','category',[['labour','ශ්‍රමය'],['materials','ද්‍රව්‍ය'],['equipment','උපකරණ'],['other','වෙනත්']])+amount()+field('Expense දිනය','date','date',today(),true,`max="${today()}"`)+noteField('විස්තරය','note',true)+photoField()+check('එකම විස්තර සහ මුදල තිබුණත් අමතර bill එකක් ලෙස තහවුරු කරමි','confirmDuplicate'),'Submit')):''}${filterBar()}${card('Bills / expenses',table(['Bill','මුදල','Status','Actions'],filtered(D.bills).slice().reverse().map(b=>[`${receipt(b.photo)} <strong>${esc(b.note)}</strong><br><small>${esc(name(b.user))} · ${esc(pn(b.project))}<br>${esc(b.date)} · ${esc(b.category)}</small>`,money(b.amount),badge(b.status)+(b.reason?`<br><small>${esc(b.reason)}</small>`:''),A()?(b.status==='pending'?btn('Approve','bill-approve',b.id)+btn('Reject','bill-reject',b.id,'danger small'):b.status==='approved'?btn('Reverse','bill-reverse',b.id,'danger small'):'—'):b.status==='rejected'?btn('Edit & resubmit','bill-resubmit',b.id):'—'])))} `;}
function storesView(){return `${A()?`<div class="actions">${btn('＋ Item එකතු කරන්න','item-new')}</div>`:card('Equipment ඉල්ලන්න',form('stock.request',pselect()+select('Item','item',[['','තෝරන්න'],...D.items.filter(i=>i.stock>0).map(i=>[i.id,`${i.code} · ${i.name} (ඇත ${i.stock})`])],'',true)+quantity(),'Request'))}${filterBar(false)}${card('Stores inventory',table(['Item','Available / Total','Missing / Damaged','Actions'],filtered(D.items).map(i=>[`${esc(i.code)}<br><strong>${esc(i.name)}</strong><br><small>${esc(i.kind)}</small>`,`${i.stock} / ${i.total}`,`${i.missing} / ${i.damaged}`,A()?btn('Adjust stock','item-adjust',i.id):'—'])))}${card('Project equipment',table(['Project','Item','ගණන / භාරකරු','Action'],D.equipment.filter(e=>e.quantity>0).map(e=>[esc(pn(e.project)),esc(item(e.item)),`${e.quantity}<br><small>${esc(name(e.effectiveHolder||e.holder))}</small>`,!A()?btn('Return / report','stock-return',e.id):'—'])))}${card('Requests / returns',table(['විස්තරය','ගණන','Status','Action'],filtered(D.stockRequests).slice().reverse().map(r=>[`${r.kind==='issue'?'Issue':'Return / '+esc(r.condition)} · ${esc(item(r.item))}<br><small>${esc(name(r.user))} · ${esc(pn(r.project))}</small>`,esc(r.quantity),badge(r.status)+(r.reason?`<br><small>${esc(r.reason)}</small>`:''),A()&&r.status==='pending'?btn('Accept','stock-approve',r.id)+btn('Reject','stock-reject',r.id,'danger small'):'—'])))} `;}
function attendanceView(){return card('Site attendance',`<div class="note">GPS accuracy ≤ 100m සහ site radius ඇතුළත විය යුතුයි. Offline check-in වේලාව device time ලෙස සටහන් වේ; අවශ්‍ය නම් Admin පරීක්ෂා කර නිවැරදි කරයි.</div>${form('attendance',pselect(false,D.projects.filter(p=>p.status!=='archived'))+select('Action','kind',[['in','Check-in'],['out','Check-out']]),'GPS සමඟ submit කරන්න')}`)+card('Attendance history',table(['Project','In / Out','පැය','Status'],D.attendance.slice().reverse().map(r=>[esc(pn(r.project)),`${dt(r.in)}<br>${dt(r.out)}`,r.out?(r.minutes/60).toFixed(2):'—',r.offline?'Offline · Admin review':r.out?'Closed':'Active'])));}
function dailyView(){return card('දෛනික update',form('day.add',pselect()+field('ශ්‍රමිකයන් ගණන','workers','number',0,true,'min="0" max="100000" step="1"')+field('වැඩ අදියර','stage','text','',true)+field('Progress %','progress','number',0,true,'min="0" max="100" step="1"')+noteField('සටහන්')+photoField(),'Submit'))+card('මගේ updates',table(['Project / වැඩ අදියර','Workers','Progress','Photo / Edit'],D.days.slice().reverse().map(r=>[`${esc(pn(r.project))}<br>${esc(r.stage)}<br><small>${esc(r.note)} · ${dt(r.time)}</small>`,esc(r.workers),`${r.progress===null?'Historical progress නොමැත':`${r.previousProgress}% → ${r.progress}%`}`,receipt(r.photo)+btn('Edit','day-edit',r.id)])));}
function handoverView(){
 const introduction=A()?card('Supervisor මාරු කරන්න',
 '<div class="note">පැරණි bills සහ history මුල් නමින්ම පවතී. අලුත් Supervisor තහවුරු කළ පසුව project access, තෝරාගත් මුදල සහ equipment පැවරේ. Pending stock සහ active attendance මුලින් අවසන් කරන්න.</div>'+
 form('handover.create',pselect()+suselect()+field('භාරදෙන මුදල (රු.)','amount','number',0,true,'min="0" step="0.01"')+noteField('මාරු කිරීමට හේතුව','reason',true)+check('තාවකාලික පත්කිරීමක් (මුදල 0 තබන්න)','temporary')+
 `<div class="form-grid">${field('Temporary ආරම්භය','start','datetime-local')}${field('Temporary අවසානය','end','datetime-local')}</div><p class="muted"><small>Temporary assignment එකේ මුදල් වෙනම යවන්න. භාරයේ equipment site එකේම පවතී.</small></p>`,'Handover request හදන්න',{revision:D.revision})):
 '<div class="note">Equipment සහ මුදල් පරීක්ෂා කර ලැබීම තහවුරු කරන්න. පැරණි Supervisorගේ bills ඔබේ නමට මාරු නොවේ.</div>';
 return introduction+card('Handover history',D.handovers.slice().reverse().map(h=>`<div class="row"><div><strong>${esc(pn(h.project))}</strong> ${badge(h.status)}<p>${esc(name(h.from))} → ${esc(name(h.to))}<br><small>${esc(h.reason)}</small></p><span>${money(h.amount)}</span><p><small>${h.temporary?`Temporary: ${dt(h.start)} → ${dt(h.end)}`:`Permanent · ${dt(h.time)}`}</small></p><small>Equipment: ${h.equipment.map(e=>`${esc(item(e.item))} × ${e.quantity}`).join(', ')||'නැහැ'}</small></div><div class="actions">${h.status==='pending'&&h.to===U.id?btn('පරීක්ෂා කර ලැබුණා','handover-accept',h.id):''}${A()&&(h.status==='pending'||h.temporary&&h.status==='complete')?btn('Cancel / end','handover-cancel',h.id,'danger small'):''}</div></div>`).join('')||empty());
}
function usersView(){return card('Supervisor account එකතු කරන්න',form('user.add',field('නම','name','text','',true)+field('Email','username','email','',true,'minlength="3" autocomplete="off"')+field('Temporary password (අකුරු 10+)','password','password','',true,'minlength="10" autocomplete="new-password"'),'Account හදන්න'))+card('Supervisors',`<p class="muted">Supervisorට මේ app URL එක සහ තමන්ගේ username / temporary password එක වෙනම ආරක්ෂිතව දෙන්න.</p>${table(['Supervisor','Status','Actions'],D.users.filter(u=>u.role==='supervisor').map(u=>[`${esc(u.name)}<br><small>${esc(u.username)}</small>`,badge(u.active?'active':'inactive'),btn('Password reset','user-reset',u.id)+btn(u.active?'Deactivate':'Activate','user-active',u.id,u.active?'danger small':'secondary small')]))}`);}
function reports(){const bills=filtered(D.bills),ps=D.projects.filter(p=>!FILTER.project||p.id===FILTER.project),approved=bills.filter(b=>b.status==='approved'),pending=bills.filter(b=>b.status==='pending');const cats=['labour','materials','equipment','other'],labels=['ශ්‍රමය','ද්‍රව්‍ය','උපකරණ','වෙනත්'],colors=['#315f48','#b99b54','#7b9e8b','#cbd7c4'],sums=cats.map(c=>total(approved.filter(b=>b.category===c))),max=Math.max(...sums,1);const chart=`<svg class="svg-chart" viewBox="0 0 520 210" role="img" aria-label="Approved expenses by category">${sums.map((n,i)=>`<text x="0" y="${29+i*48}" font-size="12" fill="#506359">${labels[i]}</text><rect x="110" y="${10+i*48}" width="${n/max*260}" height="28" rx="4" fill="${colors[i]}"></rect><text x="${120+n/max*260}" y="${29+i*48}" font-size="10" fill="#203b32">${esc(money(n))}</text>`).join('')}</svg>`;const plan=p=>{const t=Date.now(),a=Date.parse(p.start),b=Date.parse(p.end)+86400000;return Math.max(0,Math.min(100,Math.round((t-a)/(b-a)*100)));};const allAtt=D.attendance.filter(r=>(!FILTER.project||r.project===FILTER.project)&&(!FILTER.user||r.user===FILTER.user)&&(!FILTER.from||r.in.slice(0,10)>=FILTER.from)&&(!FILTER.to||r.in.slice(0,10)<=FILTER.to));return `${filterBar()}<div class="actions no-print">${btn('Print / Save as PDF','print')}${btn('Bills CSV','csv-bills')}${btn('Attendance CSV','csv-attendance')}${btn('Reconciliation CSV','csv-reconciliation')}</div><p><small>Generated: ${dt(new Date().toISOString())} · ${esc(FILTER.from||'ආරම්භයේ සිට')} → ${esc(FILTER.to||today())}</small></p><div class="stats">${stat('APPROVED EXPENSES',money(total(approved)))}${stat('PENDING EXPENSES',money(total(pending)))}${stat('PROJECT BUDGETS',money(total(ps,'budget')))}${stat('WORK HOURS',(total(allAtt,'minutes')/60).toFixed(1))}</div><div class="grid">${card('Approved expenses by category',chart)}${card('Budget vs approved expenses',ps.map(p=>{const spend=total(approved.filter(b=>b.project===p.id));return `<div class="row"><div><strong>${esc(p.name)}</strong><br><small>Budget ${money(p.budget)} · Approved ${money(spend)}</small><div class="progress"><i style="width:${Math.min(100,spend/(p.budget||1)*100)}%;background:${spend>p.budget?'#a52929':'#477f59'}"></i></div></div></div>`;}).join('')||empty())}</div>${card('Plan vs actual',ps.map(p=>`<div class="row"><div><strong>${esc(p.name)}</strong><br><small>Plan ${plan(p)}% · Actual ${p.progress}%</small><div class="progress"><i style="width:${plan(p)}%;background:#b99b54"></i></div><div class="progress"><i style="width:${p.progress}%"></i></div></div></div>`).join('')||empty())}${card('Project timeline',timeline(ps))}${card('දෛනික site updates',table(['Project / Supervisor','වැඩ','Workers / Progress','Photo'],filtered(D.days).slice().reverse().map(r=>[`${esc(pn(r.project))}<br><small>${esc(name(r.user))} · ${dt(r.time)}</small>`,`${esc(r.stage)}<br><small>${esc(r.note)}</small>`,`${r.workers} / ${r.progress===null?'—':r.progress+'%'}`,receipt(r.photo)])))}${card('Attendance',table(['කවුරුන් / Project','In / Out','Hours','Action'],allAtt.slice().reverse().map(r=>[`${esc(name(r.user))}<br><small>${esc(pn(r.project))}</small>`,`${dt(r.in)}<br>${dt(r.out)}${r.offline?'<br><small>Offline · device time requires review</small>':''}`,r.out?(r.minutes/60).toFixed(2):'Active',btn('Correct','attendance-correct',r.id)])))}${card('Stock reconciliation',table(['Item','Received total','Available','Issued','Missing','Damaged','Difference'],D.items.map(i=>{const issued=total(D.equipment.filter(e=>e.item===i.id),'quantity');return [esc(i.name),i.total,i.stock,issued,i.missing,i.damaged,i.total-i.stock-issued-i.missing-i.damaged];})))}${card('Cash reconciliation',table(['Supervisor','Received','Paid out / returned','Approved expenses','Balance'],D.users.filter(u=>u.role==='supervisor').map(u=>[esc(u.name),money(total(D.transfers.filter(t=>t.to===u.id&&t.status==='received'))),money(total(D.transfers.filter(t=>t.from===u.id&&t.status==='received'))),money(total(D.bills.filter(b=>b.user===u.id&&b.status==='approved'))),money(D.balances[u.id])])))}${card('Audit history',table(['වේලාව','කවුරුන්','Action','විස්තරය'],D.audit.slice().reverse().map(r=>[dt(r.time),esc(name(r.user)),esc(r.action),esc(r.detail)])))}`;}
function timeline(ps){if(!ps.length)return empty();const mn=Math.min(...ps.map(p=>Date.parse(p.start))),mx=Math.max(...ps.map(p=>Date.parse(p.end)+86400000)),span=mx-mn||86400000;return ps.map(p=>`<small>${esc(p.name)} · ${esc(p.start)} → ${esc(p.end)}</small><div class="timeline"><i style="left:${(Date.parse(p.start)-mn)/span*100}%;width:${(Date.parse(p.end)+86400000-Date.parse(p.start))/span*100}%"></i></div>`).join('');}
function settings(){return card('මගේ account',`<p>${esc(U.name)}<br><small>${esc(U.username||'')}</small></p>`+form('password',field('දැනට ඇති password','current','password','',true,'autocomplete="current-password"')+field('අලුත් password (අකුරු 10+)','password','password','',true,'minlength="10" autocomplete="new-password"')+field('නැවත','password2','password','',true,'minlength="10"'),'Change password'))+
 card('Phone install සහ sync',`<p class="muted">Android: Chrome menu → Install app. iPhone: Safari → Share → Add to Home Screen.</p><div class="actions">${btn('Install','install')}${btn('Sync queue','sync')}</div>${queue().map(q=>`<div class="row"><div>${esc(q.op)} · ${dt(q.queuedAt)}<br><small>${esc(q.note||q.stage||'')}</small>${q.lastError?`<br><small class="negative">${esc(q.lastError)}</small>`:''}</div>${btn('ඉවත් කරන්න','queue-remove',q.requestId,'danger small')}</div>`).join('')||empty('Queue එක හිස්')}<div class="note">Online login කළ page එක විවෘතව තිබියදී bills/daily/GPS queue කළ හැකියි. පුද්ගලික ගනුදෙනු browser cache එකේ තබන්නේ නැහැ.</div>`)+
 (A()?card('Data export සහ Google Drive',`<p class="muted">Export එකට ඔබට අවසර ඇති දත්ත සහ photos ඇතුළත් වේ. Cloud login passwords/sessions ඇතුළත් නොවේ.</p><div class="actions">${btn('Data + photos download','backup')}${btn('Drive backup','drive-backup')}${btn('Project files → Drive','drive-project')}${btn('Drive disconnect','drive-disconnect')}</div><p><small>${DRIVE?'Google Client ID configured; consent අවශ්‍යයි.':'Google Drive සඳහා config.js හි Google Client ID සකස් කළ යුතුයි.'}</small></p><p class="note">Python/local JSON restore එකෙන් live cloud database replace නොකරයි. Cloud restore තවම activate කර නැහැ.</p>`):'');}
const views={dashboard,projects:projectsView,money:moneyView,bills:billsView,stores:storesView,attendance:attendanceView,daily:dailyView,handover:handoverView,reports,users:usersView,settings};
function queueAll(){try{const q=JSON.parse(localStorage.getItem('eb-offline-v2')||'[]');return Array.isArray(q)?q:[];}catch{return [];}}
function queue(){return queueAll().filter(q=>q.owner===U?.id);}
function storeQueue(q){localStorage.setItem('eb-offline-v2',JSON.stringify(q));}
function enqueue(a){if(!U)throw new Error('Login අවශ්‍යයි');const q=queueAll();if(!q.some(r=>r.requestId===a.requestId)){q.push({...a,generation:D.queueGeneration,owner:U.id,queuedAt:new Date().toISOString()});storeQueue(q);}}
async function syncQueue(){if(!navigator.onLine)return toast('Internet/server connection අවශ්‍යයි');let ok=0;for(const r of queue()){try{await api('/api/action',r);storeQueue(queueAll().filter(q=>q.requestId!==r.requestId));ok++;}catch(e){storeQueue(queueAll().map(q=>q.owner===U.id&&q.requestId===r.requestId?{...q,lastError:e.message,lastAttempt:new Date().toISOString()}:q));toast(`Queue නවතා ඇත: ${e.message}. Settings තුළ record එක පවතී.`);break;}}await refresh();if(ok)toast(`${ok} records sync වුණා`);}
async function sendAction(data){if(BUSY)return;BUSY=true;try{const r=await api('/api/action',{...data,requestId:data.requestId||uuid(),revision:data.revision??D?.revision});DIRTY=false;closeModal();if(data.op==='password'){U=null;D=null;renderAuth(false);toast('Password වෙනස් වුණා. නැවත login වෙන්න.');return;}await refresh();toast('Server එකේ save වුණා ✔');return r;}catch(e){toast(e.message);throw e;}finally{BUSY=false;}}
async function readPhoto(file){if(!file||!file.size)return '';if(!['image/jpeg','image/png'].includes(file.type)||file.size>3*1024*1024)throw new Error('JPG/PNG photo ≤ 3 MB අවශ්‍යයි');return await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(new Error('Photo කියවීමට බැහැ'));r.readAsDataURL(file);});}
async function position(){if(!navigator.geolocation)throw new Error('GPS සඳහා HTTPS හෝ localhost අවශ්‍යයි');return await new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(g=>resolve({lat:g.coords.latitude,lng:g.coords.longitude,accuracy:g.coords.accuracy,deviceTime:new Date().toISOString()}),()=>reject(new Error('GPS ලබාගත නොහැක. Location allow කර HTTPS භාවිතා කරන්න.')),{enableHighAccuracy:true,timeout:20000,maximumAge:0}));}
function validateOffline(a){const p=D.projects.find(p=>p.id===a.project);if(!p||p.status!=='ongoing')throw new Error('Active assigned project එකක් තෝරන්න');if(a.op==='attendance'){if(p.lat===null)throw new Error('Project GPS set කර නැහැ');const rad=Math.PI/180,v=Math.sin((a.lat-p.lat)*rad/2)**2+Math.cos(a.lat*rad)*Math.cos(p.lat*rad)*Math.sin((a.lng-p.lng)*rad/2)**2,distance=6371000*2*Math.asin(Math.sqrt(Math.min(1,v)));if(a.accuracy>Math.min(p.radius,100)||distance>p.radius)throw new Error('GPS accuracy / site radius ප්‍රමාණවත් නැහැ');}}
document.addEventListener('submit',async e=>{const f=e.target;if(!f.matches('form[data-op]'))return;e.preventDefault();if(BUSY)return;const op=f.dataset.op,fd=new FormData(f),a={op,requestId:f.dataset.requestId||(f.dataset.requestId=uuid())};for(const [k,v]of fd)if(typeof v==='string')a[k]=v;f.querySelectorAll('input[type=checkbox]').forEach(el=>a[el.name]=el.checked);if('revision'in a)a.revision=Number(a.revision);const err=f.querySelector('.form-error'),submit=f.querySelector('[type=submit]');err.innerHTML='';submit.disabled=true;try{
 if(a.password2!==undefined&&a.password!==a.password2)throw new Error('Passwords දෙක නොගැළපේ');
 if(op==='drive.export'){await driveProjectExport(a.project);return;}
 if(op==='backup.preview'){const file=fd.get('backup');if(!file?.size||file.size>30*1024*1024)throw new Error('Backup ≤ 30 MB අවශ්‍යයි');const b=JSON.parse(await file.text());if(b.format!=='early-birds-backup'||b.version!==2||!b.data?.users)throw new Error('වලංගු v2 backup එකක් අවශ්‍යයි');restoreFile=b;modal('Restore preview',`<div class="note">මෙය දැනට ඇති data replace කරයි. Pre-restore recovery snapshot එකක් server එකේ තබයි. සියලු devices නැවත login විය යුතුයි.</div><p>Created: ${esc(dt(b.created))}<br>Users: ${b.data.users.length}<br>Projects: ${b.data.projects?.length||0}<br>Bills: ${b.data.bills?.length||0}<br>Photos: ${b.files?.length||0}</p>${form('backup.restore',field('දැනට ඇති Admin password','current','password','',true)+check('දැනට ඇති workspace එක replace කිරීමට එකඟයි','confirmed'),'Restore workspace')}`);return;}
 if(op==='legacy.import'){if(!a.confirmed)throw new Error('Import confirmation අවශ්‍යයි');const file=fd.get('legacy');if(!file?.size||file.size>30*1024*1024)throw new Error('Legacy JSON ≤ 30 MB අවශ්‍යයි');const parsed=JSON.parse(await file.text());a.legacy=parsed.data||parsed;}
 if(op==='backup.restore'){if(!a.confirmed||!restoreFile)throw new Error('Restore confirmation අවශ්‍යයි');a.backup=restoreFile;}
 if(op==='handover.create'&&a.temporary){if(!a.start||!a.end)throw new Error('Temporary ආරම්භය සහ අවසානය අවශ්‍යයි');a.start=new Date(a.start).toISOString();a.end=new Date(a.end).toISOString();}
 if(fd.get('photo')?.size)a.photo=await readPhoto(fd.get('photo'));
 if(op==='attendance')Object.assign(a,await position());
 if(['bill.add','day.add','attendance'].includes(op)&&!navigator.onLine){a.offline=true;validateOffline(a);enqueue(a);DIRTY=false;f.reset();delete f.dataset.requestId;render();toast('Offline queue එකේ තබා ඇත. තවම server save කර නැහැ.');return;}
 if(['setup','login','backup.restore','legacy.import'].includes(op)){const res=await api('/api/action',a);DIRTY=false;closeModal();restoreFile=null;await refresh();if(op==='legacy.import'){modal('Import අවසන් — review අවශ්‍යයි',`<p>Reports තුළ cash/stock reconciliation පරීක්ෂා කරන්න. Users tab එකෙන් එක් එක් Supervisorගේ password reset කර ලබාදෙන්න.</p>${table(['නම','Username'],res.accounts.map(u=>[esc(u.name),esc(u.username)]))}`);return;}toast(op==='backup.restore'?'Restore වුණා. Backup එකේ password සමඟ නැවත login වෙන්න.':'Login වුණා ✔');}
 else {const result=await sendAction(a);if(result)delete f.dataset.requestId;}
 }catch(error){if(error.network&&['bill.add','day.add','attendance'].includes(op)&&a.project){try{a.offline=true;validateOffline(a);enqueue(a);DIRTY=false;render();toast('Server ලැබීම තහවුරු නැහැ. Retry සඳහා queue එකේ ඇත.');return;}catch(qe){error=qe;}}err.innerHTML=`<div class="error">${esc(error.message)}</div>`;toast(error.message);}finally{submit.disabled=false;}});
document.addEventListener('input',e=>{if(e.target.closest('form'))DIRTY=true;});
let filterTimer;
document.addEventListener('input',e=>{if(!e.target.dataset.filter)return;if(DIRTY){e.target.value=FILTER[e.target.dataset.filter]||'';toast('මුලින් form එක save කරන්න හෝ Refresh කර ඉවත් කරන්න.');return;}const key=e.target.dataset.filter,val=e.target.value;FILTER[key]=val;clearTimeout(filterTimer);filterTimer=setTimeout(()=>{render();const el=$(`[data-filter="${key}"]`);if(el){el.focus();if(el.type==='text')el.setSelectionRange(val.length,val.length);}},350);});
document.addEventListener('change',e=>{if(e.target.name==='project'&&e.target.closest('form')?.dataset.op==='day.add'){const p=D.projects.find(p=>p.id===e.target.value);if(p)e.target.closest('form').querySelector('[name=progress]').value=p.progress;}if(e.target.dataset.filter){if(DIRTY){e.target.value=FILTER[e.target.dataset.filter]||'';toast('මුලින් form එක save කරන්න.');return;}FILTER[e.target.dataset.filter]=e.target.value;render();}});
function reasonModal(title,op,id,extra={}){modal(title,form(op,noteField('හේතුව','reason',true),title,{id,...extra}));}
const actions={
 'legacy-export':()=>{if(!confirm('පැරණි data private export එකක් download කරන්නද? File එක ආරක්ෂිතව තබන්න.'))return;const data=JSON.parse(localStorage.getItem('eb2')||'{}');if(!data||typeof data!=='object'||Array.isArray(data))throw new Error('පැරණි data format එක වැරදියි');data.u=(Array.isArray(data.u)?data.u:[]).map(u=>{const r={...u};delete r.h;delete r.password;delete r.pw;return r;});const q=JSON.parse(localStorage.getItem('ebq')||'[]');data.c=[...new Map([...(Array.isArray(data.c)?data.c:[]),...(Array.isArray(q)?q:[])].map(r=>[r.id,r])).values()];downloadJSON({format:'early-birds-legacy',created:new Date().toISOString(),data},'early-birds-legacy-private-export.json');toast('Export download කළා. පැරණි browser data වෙනස් කර නැහැ.');},
 refresh:async()=>{if(DIRTY&&!confirm('ඇතුළත් කර ඇති unsaved විස්තර ඉවත් කර Refresh කරන්නද?'))return;DIRTY=false;await refresh();},
 logout:async()=>{if(queue().length&&!confirm('Sync නොකළ records ඇත. Logout කළත් මේ device එකේ ඔබේ account එක යටතේ පවතී. Logout කරන්නද?'))return;if(DIRTY&&!confirm('Unsaved විස්තර ඉවත් කර Logout කරන්නද?'))return;++STATE_REQUEST;await api('/api/action',{op:'logout'});driveToken='';D=null;U=null;DIRTY=false;renderAuth(false);},
 'project-new':()=>modal('අලුත් project',projectForm()),
 'project-edit':id=>modal('Project edit',projectForm(D.projects.find(p=>p.id===id))),
 'gps-project':async()=>{const g=await position();$('#modal [name=lat]').value=g.lat;$('#modal [name=lng]').value=g.lng;DIRTY=true;toast('GPS ලැබුණා');},
 receive:id=>{if(confirm('මෙම මුදල ඇත්තටම ලැබුණු බව තහවුරු කරන්නද?'))return sendAction({op:'money.receive',id});},
 'money-reverse':id=>reasonModal('Received transfer reverse — balance වෙනස් වේ','money.reverse',id),
 'money-cancel':id=>reasonModal('Transfer cancel','money.cancel',id),
 'request-approve':id=>sendAction({op:'request.decide',id,approve:true}),
 'request-reject':id=>reasonModal('Request reject','request.decide',id),
 'bill-approve':id=>sendAction({op:'bill.decide',id,approve:true}),
 'bill-reject':id=>reasonModal('Bill reject','bill.decide',id),
 'bill-reverse':id=>reasonModal('Approved bill reverse','bill.reverse',id),
 'bill-resubmit':id=>{const b=D.bills.find(b=>b.id===id);modal('Bill edit & resubmit',form('bill.resubmit',field('මුදල (රු.)','amount','number',b.amount/100,true,'min="0.01" step="0.01"')+field('විස්තරය','note','text',b.note,true),'Resubmit',{id}));},
 'day-edit':id=>{const r=D.days.find(r=>r.id===id);modal('Daily update edit',form('day.edit',field('ශ්‍රමිකයන් ගණන','workers','number',r.workers,true,'min="0" step="1"')+field('වැඩ අදියර','stage','text',r.stage,true)+field('Progress %','progress','number',r.progress,true,'min="0" max="100" step="1"')+field('සටහන්','note','text',r.note),'Save — history රැකේ',{id,revision:D.revision}));},
 'item-new':()=>modal('අලුත් item',form('item.add',field('Item code','code','text','',true)+field('නම','name','text','',true)+select('වර්ගය','kind',[['tools','මෙවලම්'],['safety','ආරක්ෂක උපකරණ'],['materials','ද්‍රව්‍ය']])+field('මුල් තොගය','quantity','number',0,true,'min="0" step="1"'),'Add item')),
 'item-adjust':id=>modal('Stock adjustment',form('item.adjust',select('Action','kind',[['receive','අලුතින් ලැබුණු තොගය'],['missing','Store එකෙන් missing'],['damaged','Store එකේ damaged'],['recover','Missing නැවත ලැබුණා'],['repair','Damaged අලුත්වැඩියා වුණා']])+quantity()+noteField('හේතුව','reason',true),'Save adjustment',{id})),
 'stock-return':id=>{const e=D.equipment.find(e=>e.id===id);modal('Equipment return / loss',form('stock.return',`<p>${esc(item(e.item))} · භාරයේ ${e.quantity}</p>`+quantity()+select('තත්ත්වය','condition',[['good','හොඳ තත්ත්වයෙන් return'],['damaged','Damaged'],['missing','Missing']]),'Submit',{id}));},
 'stock-approve':id=>sendAction({op:'stock.decide',id,approve:true}),
 'stock-reject':id=>reasonModal('Stock request reject','stock.decide',id),
 'handover-accept':id=>{if(confirm('ලැයිස්තුවේ මුදල් සහ උපකරණ පරීක්ෂා කර ලැබුණු බව තහවුරු කරන්නද?'))return sendAction({op:'handover.accept',id});},
 'handover-cancel':id=>reasonModal('Handover cancel / end','handover.cancel',id),
 'user-reset':id=>modal('Supervisor password reset',form('user.reset',field('අලුත් temporary password','password','password','',true,'minlength="10" autocomplete="new-password"'),'Reset — සියලු sessions අවසන් වේ',{id})),
 'user-active':id=>{if(confirm('මෙම account තත්ත්වය වෙනස් කරන්නද?'))return sendAction({op:'user.active',id});},
 'attendance-correct':id=>{const r=D.attendance.find(r=>r.id===id);modal('Attendance correction',form('attendance.correct',field('Check-in ISO time (timezone සමඟ)','in','text',r.in,true)+field('Check-out ISO time (timezone සමඟ)','out','text',r.out||new Date().toISOString(),true)+noteField('හේතුව','reason',true),'Save correction',{id}));},
 sync:syncQueue,
 'queue-remove':id=>{if(confirm('Sync නොකළ record එක ස්ථිරව ඉවත් කරන්නද?')){storeQueue(queueAll().filter(q=>!(q.owner===U.id&&q.requestId===id)));render();}},
 more:()=>{LIMIT+=40;render();},print:()=>window.print(),
 backup:async()=>downloadJSON(await api('/api/backup'),`early-birds-phone-export-${today()}.json`),
 'drive-backup':driveBackup,
 'drive-project':()=>modal('Project photos සහ report → Drive',`<div class="note">Photos සහ project report එක ඔබේ private Drive එකේ project folder එකකට upload වේ. App accounts තුළ passwords හෝ login details මේ export එකට ඇතුළත් නොවේ.</div>${form('drive.export',pselect(false,D.projects),'Upload project files')}`),
 'drive-disconnect':()=>{if(driveToken&&window.google?.accounts?.oauth2)google.accounts.oauth2.revoke(driveToken,()=>{});driveToken='';driveExpires=0;toast('Drive access මේ app එකෙන් ඉවත් කළා');},
 install:async()=>{if(INSTALL_PROMPT){const prompt=INSTALL_PROMPT;INSTALL_PROMPT=null;await prompt.prompt();await prompt.userChoice;return;}modal('Phone එකට app එක දාන්න','<p>Android: Chrome menu → Install app / Add to Home screen.</p><p>iPhone: Safari → Share → Add to Home Screen → Open as Web App → Add.</p><p class="note">GitHub Pages HTTPS link එක භාවිතා කරන්න. Computer එකක් ක්‍රියාත්මකව තබන්න අවශ්‍ය නැහැ.</p>');},
 'csv-bills':()=>csv('bills',['ID','Project','Supervisor','Date','Category','Description','Amount LKR','Status'],filtered(D.bills).map(b=>[b.id,pn(b.project),name(b.user),b.date,b.category,b.note,(b.amount/100).toFixed(2),b.status])),
 'csv-attendance':()=>csv('attendance',['ID','Supervisor','Project','Check in','Check out','Hours','Offline'],D.attendance.filter(r=>(!FILTER.project||r.project===FILTER.project)&&(!FILTER.user||r.user===FILTER.user)&&(!FILTER.from||r.in.slice(0,10)>=FILTER.from)&&(!FILTER.to||r.in.slice(0,10)<=FILTER.to)).map(r=>[r.id,name(r.user),pn(r.project),r.in,r.out,r.out?(r.minutes/60).toFixed(2):'',r.offline])),
 'csv-reconciliation':()=>csv('reconciliation',['Supervisor','Received LKR','Paid out LKR','Approved expenses LKR','Balance LKR'],D.users.filter(u=>u.role==='supervisor').map(u=>[u.name,(total(D.transfers.filter(t=>t.to===u.id&&t.status==='received'))/100).toFixed(2),(total(D.transfers.filter(t=>t.from===u.id&&t.status==='received'))/100).toFixed(2),(total(D.bills.filter(b=>b.user===u.id&&b.status==='approved'))/100).toFixed(2),((D.balances[u.id]||0)/100).toFixed(2)]))
};
document.addEventListener('click',async e=>{const tab=e.target.closest('[data-tab]');if(tab){if(DIRTY&&!confirm('Unsaved විස්තර ඉවත් කර tab මාරු කරන්නද?'))return;T=tab.dataset.tab;FILTER={q:'',project:'',status:'',from:'',to:'',user:''};LIMIT=40;DIRTY=false;render();window.scrollTo(0,0);return;}const b=e.target.closest('[data-action]');if(!b)return;try{b.disabled=true;await actions[b.dataset.action]?.(b.dataset.id);}catch(e){toast(e.message);}finally{b.disabled=false;}});
$('#closeModal').addEventListener('click',()=>{if(!DIRTY||confirm('Unsaved විස්තර ඉවත් කරන්නද?'))closeModal();});
$('#modal').addEventListener('cancel',e=>{if(DIRTY&&!confirm('Unsaved විස්තර ඉවත් කරන්නද?'))e.preventDefault();else DIRTY=false;});
function download(blob,filename){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function downloadJSON(data,filename){download(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),filename);}
function csv(name,headers,rows){const safe=v=>{let s=String(v??'');if(/^[\s]*[=+\-@]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};download(new Blob(['\uFEFF'+[headers,...rows].map(r=>r.map(safe).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),`early-birds-${name}-${today()}.csv`);}
async function loadGoogle(){if(window.google?.accounts?.oauth2)return;await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://accounts.google.com/gsi/client';s.onload=resolve;s.onerror=()=>reject(new Error('Google sign-in load වුණේ නැහැ'));document.head.append(s);});}
async function driveAuth(){
 if(!DRIVE)throw new Error('EB_GOOGLE_CLIENT_ID සකස් කරන්න. Setup guide බලන්න.');
 await loadGoogle();if(driveToken&&Date.now()<driveExpires)return;
 await new Promise((resolve,reject)=>{const client=google.accounts.oauth2.initTokenClient({client_id:DRIVE,scope:'https://www.googleapis.com/auth/drive.file',callback:r=>{if(r.error)return reject(new Error(r.error));driveToken=r.access_token;driveExpires=Date.now()+(r.expires_in-60)*1000;resolve();},error_callback:()=>reject(new Error('Google authorization අවසන් කළේ නැහැ. නැවත button එක ඔබන්න.'))});client.requestAccessToken();});
}
async function driveRequest(url,opts={}){const r=await fetch(url,{...opts,headers:{Authorization:'Bearer '+driveToken,...(opts.headers||{})}});if(!r.ok){if(r.status===401)driveToken='';throw new Error('Drive upload/list අසාර්ථකයි. Local copy එක තබා නැවත උත්සාහ කරන්න.');}return await r.json();}
async function driveFolder(name,parent=''){
 const quote=s=>s.replace(/\\/g,'\\\\').replace(/'/g,"\\'");
 const q=`name='${quote(name)}' and mimeType='application/vnd.google-apps.folder' and trashed=false`+(parent?` and '${quote(parent)}' in parents`:'');
 const query=new URLSearchParams({q,fields:'files(id,name)',pageSize:'100'});
 const r=await driveRequest('https://www.googleapis.com/drive/v3/files?'+query);
 if(r.files?.length)return r.files[0].id;
 const folder=await driveRequest('https://www.googleapis.com/drive/v3/files?fields=id',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,mimeType:'application/vnd.google-apps.folder',...(parent?{parents:[parent]}:{})})});return folder.id;
}
async function driveUpload(name,mime,data,parent){
 const boundary='eb'+uuid(),meta={name,mimeType:mime,parents:[parent]};
 const body=new Blob([`--${boundary}\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n${JSON.stringify(meta)}\r\n--${boundary}\r\nContent-Type: ${mime}\r\n\r\n`,data,`\r\n--${boundary}--`]);
 return await driveRequest('https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&fields=id,name,webViewLink',{method:'POST',headers:{'Content-Type':'multipart/related; boundary='+boundary},body});
}
async function driveBackup(){
 await driveAuth();const backup=await api('/api/backup');
 const root=await driveFolder('Early Birds'),folder=await driveFolder('Backups',root);
 const file=await driveUpload(`Early-Birds-backup-${new Date().toISOString().replace(/[:.]/g,'-')}.json`,'application/json',JSON.stringify(backup),folder);
 modal('Drive backup save වුණා',`<p>${esc(file.name)}</p><p>Drive → Early Birds → Backups තුළ ඇත. මෙය data/photo export එකකි. Cloud Auth passwords ඇතුළත් නැහැ; live restore වෙනම review කළ යුතුයි.</p><a href="https://drive.google.com/drive/folders/${encodeURIComponent(folder)}" target="_blank" rel="noopener">Backup folder එක බලන්න</a>`);
}
async function driveProjectExport(projectId){
 await driveAuth();const b=await api('/api/backup'),p=b.data.projects.find(p=>p.id===projectId);if(!p)throw new Error('Project හමු නොවීය');
 const root=await driveFolder('Early Birds'),projectsFolder=await driveFolder('Projects',root),folder=await driveFolder(`${p.name} [${p.id.slice(0,8)}]`,projectsFolder),stamp=new Date().toISOString().replace(/[:.]/g,'-'),batch=await driveFolder('Export '+stamp,folder),photos=await driveFolder('Photos',batch);
 let count=0;for(const f of b.files.filter(f=>f.project===p.id)){const bytes=Uint8Array.from(atob(f.data),c=>c.charCodeAt(0)),ext={'image/jpeg':'jpg','image/png':'png','image/webp':'webp'}[f.mime];await driveUpload(`${f.id}.${ext}`,f.mime,bytes,photos);count++;toast(`Drive photos upload: ${count}`);}
 const report={generated:new Date().toISOString(),project:p,bills:b.data.bills.filter(r=>r.project===p.id),dailyUpdates:b.data.days.filter(r=>r.project===p.id),attendance:b.data.attendance.filter(r=>r.project===p.id),equipment:b.data.equipment.filter(r=>r.project===p.id),handovers:b.data.handovers.filter(r=>r.project===p.id),approvedExpenseCents:total(b.data.bills.filter(r=>r.project===p.id&&r.status==='approved')),pendingExpenseCents:total(b.data.bills.filter(r=>r.project===p.id&&r.status==='pending'))};
 await driveUpload('Project-report.json','application/json',JSON.stringify(report,null,2),batch);
 closeModal();modal('Project export save වුණා',`<p>${esc(p.name)} · Photos ${count} + project report</p><p>මේවා private exports. Supervisorට Drive folder sharing වෙනම සකස් නොකළහොත් access නැහැ. App permissions Drive sharing ස්වයංක්‍රීයව වෙනස් කරන්නේ නැහැ.</p><a href="https://drive.google.com/drive/folders/${encodeURIComponent(batch)}" target="_blank" rel="noopener">Export folder එක බලන්න</a>`);
}
addEventListener('beforeinstallprompt',e=>{e.preventDefault();INSTALL_PROMPT=e;});
addEventListener('appinstalled',()=>{INSTALL_PROMPT=null;toast('Early Birds Home Screen එකට එක් වුණා');});
addEventListener('online',()=>{toast('Connection ආවා. Settings → Sync queue භාවිතා කරන්න.');if(!DIRTY&&!$('#modal').open)refresh();});
addEventListener('offline',()=>{toast('Offline. Bills සහ daily updates queue කළ හැකියි.');});
addEventListener('beforeunload',e=>{if(DIRTY){e.preventDefault();e.returnValue='';}});
setInterval(()=>{if(U&&!DIRTY&&!BUSY&&!$('#modal').open&&navigator.onLine)refresh();},30000);
if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js',{scope:'./'}).catch(()=>{});
refresh();
